    ]

    /// The gate the reference applied, `[position][copy]`.
    private static let expectedGates: [Float] = [
        0.5560219287872314, 0.6377276182174683, 0.6284303665161133, 0.6536403894424438,
    ]

    private func matrix(rows: Int, columns: Int, _ values: [Float]) -> DeepSeekV41Matrix {
        DeepSeekV41Matrix(rows: rows, columns: columns, values: values)
    }

    private let positions = 2
    private let hashColumns = 2
    private let headDim = 32

    private func contribution(position: Int) throws -> DeepSeekV41EngramCombination.Contribution {
        let residual = (0..<copies).map { copy in
            let start = (position * copies + copy) * dim
            return Array(Self.residual[start..<(start + dim)])
        }
        let rows = (0..<hashColumns).map { column in
            let start = (position * hashColumns + column) * headDim
            return Array(Self.rows[start..<(start + headDim)])
        }
        return try XCTUnwrap(
            DeepSeekV41EngramCombination.contribution(
                residual: residual,
                rows: rows,
                wkv: matrix(rows: dim * (copies + 1), columns: hashColumns * headDim, Self.wkv),
                queryWeight: Self.queryWeight,
                keyWeight: Self.keyWeight,
                epsilon: eps
            )
        )
    }

    func testStreamsMatchTheReference() throws {
        for position in 0..<positions {
            let result = try contribution(position: position)
            for copy in 0..<copies {
                for dimension in 0..<dim {
                    let expected = Self.expectedStreams[
                        (position * copies + copy) * dim + dimension
                    ]
                    XCTAssertEqual(
                        result.streams[copy][dimension],
                        expected,
                        accuracy: 1e-4,
                        "position \(position) copy \(copy) dim \(dimension)"
                    )
                }
            }
        }
    }

    func testGatesMatchTheReference() throws {
        for position in 0..<positions {
            let result = try contribution(position: position)
            for copy in 0..<copies {
                XCTAssertEqual(
                    result.gates[copy],
                    Self.expectedGates[position * copies + copy],
                    accuracy: 1e-4,
                    "position \(position) copy \(copy)"
                )
            }
        }
    }
}

// MARK: - Compressor pooling

/// `Compressor.forward`: one block of positions pooled into one latent, with the
/// softmax over the GROUP axis per dimension.
///
/// The four positions disagree about which one should dominate, so a kernel that
/// shared one weight per row (the group mean) lands somewhere else in every
/// component. `pooled` is the module's output with its `RMSNorm` replaced by
/// `Identity`, which is the pooling rule on its own; `postNorm` is the module's
/// real return value, so the norm is in the comparison too.
final class DeepSeekV41CompressorGoldenTests: XCTestCase {

    private let eps: Float = 1e-06
    private let width = 4
    private let hidden = 8
    private let ratio = 2

    /// `[position][dim]`, the block's inputs in ascending position order.
    private static let positions: [Float] = [
        1.0, 0.0, 2.0, -1.0, 0.5, 1.5, -0.5, 3.0,
        0.0, 1.0, -1.0, 2.0, 4.0, -2.0, 1.0, 0.25,
        2.0, -3.0, 0.5, 1.0, -1.5, 0.75, 2.5, -0.25,
        -1.0, 2.0, 3.0, 0.5, 1.0, -4.0, -2.0, 1.5,
    ]

    /// `attn.compressor.wkv`, `[head_dim][dim]`, row-major.
    private static let kvWeight: [Float] = [
        -0.2743486762046814, -0.29252973198890686, -0.11096779257059097, 0.2449793964624405, 0.1938299536705017, 0.0271333996206522, 0.5312392115592957, -0.23078827559947968,
        -0.10173508524894714, -0.10976564139127731, -0.32761093974113464, -0.18267247080802917, -0.9094019532203674, -0.20123140513896942, 0.015708519145846367, -0.18294356763362885,
        0.14256815612316132, -0.3770979046821594, 0.584096372127533, 0.02197224833071232, -0.42252734303474426, -0.21017824113368988, -0.42883339524269104, 0.207710862159729,
        -0.26240235567092896, 0.2526072561740875, 0.5875536203384399, 0.28500065207481384, -0.07786837220191956, -0.3613465428352356, -0.4851985275745392, -0.040346261113882065,
    ]

    /// `attn.compressor.wgate`, `[head_dim][dim]`, row-major.
    private static let gateWeight: [Float] = [
        -0.2961757779121399, -0.19481568038463593, 0.0826670229434967, 0.5185345411300659, 0.10048672556877136, -0.31101828813552856, -0.39707642793655396, -0.09807982295751572,
        0.15090014040470123, -0.021074937656521797, -0.41118288040161133, 0.9671960473060608, -0.21570582687854767, 0.29945796728134155, -0.3636859655380249, -0.35620594024658203,
        -0.2053443193435669, 0.07546232640743256, 0.22728553414344788, 0.41214895248413086, -0.18166284263134003, -0.22688943147659302, 0.07892361283302307, -0.0828431099653244,
        0.19894123077392578, 0.19902102649211884, -0.22693189978599548, -0.2658155858516693, 0.02506062760949135, 0.002452727174386382, 0.21632415056228638, -0.07565955817699432,
    ]

    private static let normGain: [Float] = [
        1.1576294898986816, 0.8955057263374329, 1.463687539100647, 1.2533512115478516,
    ]

    /// `[group][head_dim]`, un-normalised: `pooledLatent`'s output.
    private static let pooled: [Float] = [
        1.2754789590835571, -3.306647300720215, -1.6998227834701538, 0.1575489044189453, -1.7089918851852417, 0.9526156783103943, 2.1994235515594482, -0.2981584072113037,
    ]

    /// `[group][head_dim]`, the module's own return value.
    private static let postNorm: [Float] = [
        0.7506850361824036, -1.5054665803909302, -1.2649312019348145, 0.1003929078578949, -1.337285041809082, 0.5766343474388123, 2.1760640144348145, -0.2526005208492279,
    ]

    private func inputs(group: Int) -> [[Float]] {
        (0..<ratio).map { offset in
            let start = (group * ratio + offset) * hidden
            return Array(Self.positions[start..<(start + hidden)])
        }
    }

    func testPoolingMatchesTheReference() throws {
        for group in 0..<2 {
            let pooled = DeepSeekV41Compressor.pooledLatent(
                inputs: inputs(group: group),
                kvWeight: DeepSeekV41Matrix(rows: width, columns: hidden, values: Self.kvWeight),
                gateWeight: DeepSeekV41Matrix(rows: width, columns: hidden, values: Self.gateWeight)
            )
            for dimension in 0..<width {
                XCTAssertEqual(
                    pooled[dimension],
                    Self.pooled[group * width + dimension],
                    accuracy: 1e-4,
                    "group \(group) dim \(dimension)"
                )
            }

            // The module's real return value, `RMSNorm(pooled)`.
            let squares = pooled.reduce(Float(0)) { $0 + $1 * $1 }
            let rstd = 1 / (squares / Float(width) + eps).squareRoot()
            for dimension in 0..<width {
                XCTAssertEqual(
                    pooled[dimension] * rstd * Self.normGain[dimension],
                    Self.postNorm[group * width + dimension],
                    accuracy: 1e-4,
                    "group \(group) dim \(dimension) after the norm"
                )
            }
        }
    }
}

// MARK: - Router scoring

/// `Gate.forward`: which experts the mixture runs and with what weights.
///
/// Both scorings are pinned over the SAME weights, because they are not rescalings
/// of each other: `sqrtsoftplus` (the shipped one) and `sigmoid` select different
/// experts here. `gate_temp` is 0.7 rather than 1, so a port that divided the logits
/// after the scoring function instead of before it cannot pass by accident.
final class DeepSeekV41RouterGoldenTests: XCTestCase {

    private let dim = 8
    private let experts = 6
    private let topK = 2
    private let gateTemp: Float = 0.7
    private let routeScale: Float = 2.5
    private let normTopKProb = true

    /// `[token][dim]`, the router's input.
    private static let tokens: [Float] = [
        1.0, 0.5, -2.0, 1.5, 0.0, 2.0, -1.0, 0.25,
        -1.0, 2.0, 1.0, -0.5, 1.5, -2.0, 0.5, 1.0,
        0.25, -0.75, 0.5, 2.0, -1.5, 1.0, 1.0, -1.0,
    ]

    /// `ffn.gate`, `[n_routed_experts][dim]`, row-major.
    private static let weight: [Float] = [
        -0.15965794026851654, -0.425629198551178, -0.31909048557281494, -0.2128576785326004, 0.7155305743217468, 0.23559899628162384, -0.15591754019260406, -0.16417895257472992,
        0.5504508018493652, 0.7900717258453369, 0.27652549743652344, 0.47595518827438354, -0.13340799510478973, 0.3461524248123169, -0.3558898866176605, 0.5262559652328491,
        -0.1514802724123001, -0.4057750403881073, 0.5026953816413879, -0.15667544305324554, -0.6018968820571899, -0.6000679731369019, 0.01435739453881979, 0.23815803229808807,
        0.4198357164859772, -0.18680240213871002, -0.2016441971063614, 0.7312984466552734, -0.11190355569124222, -0.03756757080554962, -0.030809979885816574, 0.4146031141281128,
        -0.4289177358150482, 0.2188664823770523, -0.18069885671138763, 0.25762972235679626, 0.11628817766904831, -0.5075194835662842, -0.17188766598701477, -0.8294000625610352,
        0.49902400374412537, 0.2823798954486847, -0.013951428234577179, -0.011874676682054996, 0.4134485721588135, -0.10586526244878769, -0.4660976231098175, 0.40850505232810974,
    ]

    /// `ffn.gate.bias`, one per expert: it steers SELECTION and never scales the
    /// chosen expert.
    private static let bias: [Float] = [
        -0.21611110866069794, 0.15694977343082428, -0.7909045219421387, -0.2851794362068176, -0.07134311646223068, 0.577670693397522,
    ]

    private func expectRouting(
        scoringFunction: DeepSeekV41ScoringFunction,
        indices: [Int],
        weights: [Float]
    ) {
        for token in 0..<(Self.tokens.count / dim) {
            // The projection the executor runs before `route`: one dot per expert.
            let logits = (0..<experts).map { expert in
                (0..<dim).reduce(Float(0)) { total, dimension in
                    total + Self.weight[expert * dim + dimension]
                        * Self.tokens[token * dim + dimension]
                }
            }
            let routing = DeepSeekV41Router.route(
                logits: logits,
                bias: Self.bias,
                topK: topK,
                scalingFactor: routeScale,
                normalise: normTopKProb,
                scoringFunction: scoringFunction,
                gateTemp: gateTemp
            )
            for rank in 0..<topK {
                XCTAssertEqual(
                    routing.expertIDs[rank],
                    indices[token * topK + rank],
                    "token \(token) rank \(rank)"
                )
                XCTAssertEqual(
                    routing.weights[rank],
                    weights[token * topK + rank],
                    accuracy: 1e-4,
                    "token \(token) rank \(rank)"
                )
            }
        }
    }

    func testSqrtsoftplusRoutesLikeTheReference() {
        expectRouting(
            scoringFunction: .sqrtsoftplus,
            indices: [1, 5, 5, 1, 3, 1],
            weights: [
        1.4645452499389648, 1.0354547500610352, 1.3789886236190796, 1.12101149559021, 1.4853057861328125, 1.0146942138671875,
            ]
        )
    }

    func testSigmoidRoutesLikeTheReference() {
        expectRouting(
            scoringFunction: .sigmoid,
            indices: [5, 1, 5, 1, 1, 5],
            weights: [
        1.140588641166687, 1.359411358833313, 1.368239402770996, 1.131760597229004, 2.2111148834228516, 0.2888849675655365,
            ]
        )
    }
}

// MARK: - DSpark draft chain

/// `DSparkBlock.forward_head`: which token each draft step produces.
///
/// Three things are pinned here, in the order they can go wrong:
///
///  * the Markov head is a projection over the token BEFORE the draft, and its
///    contribution is ADDED to the draft head's logits rather than mixed with
///    them (`logits[:, i].add_(logits_bias)` in the reference);
///  * at temperature 0 the draw is the argmax, and at temperature > 0 it is
///    Gumbel-max — the two chains below disagree, so a port that only implements
///    argmax cannot pass both;
///  * the chain conditions each step on the token it drew itself. The reference run
///    that produced these numbers drove its draws from the recorded uniform table
///    rather than torch's RNG, which is what lets another implementation replay
///    them at all.
///
/// What is NOT here: the block's own attention and MoE, which the reference only
/// runs through `forward_spec` (nothing in its generator calls it), and
/// `confidence_head`, whose output the runtime supplies per step. `main_proj` /
/// `main_norm` are likewise device work; the vectors carry `main_x` so a device
/// run has something to compare against later.
final class DeepSeekV41DSparkGoldenTests: XCTestCase {

    private let vocab = 16
    private let rank = 4
    private let blockSize = 3
    private let seedToken = 11

    /// [vocab][rank]: the Markov head's token embedding, row per token.
    private static let markovEmbedding: [Float] = [
        0.07505525648593903, 0.5770904421806335, 0.631659984588623, 0.23289524018764496,
