        3.411820411682129, 0.9594517946243286, 0.02313859760761261, 0.3091300129890442, 2.3994224071502686,
        -0.5638052225112915, 0.22802963852882385, 0.39270687103271484, 0.019546233117580414, -0.4860023856163025,
    ]

    /// `encoding/encoding.py`'s `IMAGE_PLACEHOLDER`, one codepoint at a time.
    private static let markerCodepoints: [UInt32] = [60, 65372, 100, 101, 101, 112, 115, 101, 101, 107, 95, 105, 109, 97, 103, 101, 65372, 62]

    private func spec() -> DeepSeekV41VisionSpec {
        DeepSeekV41VisionSpec(
            patchSize: patchSize,
            downsampleRatio: ratio,
            minPixels: 0,
            maxImageTokens: 1_024,
            numHiddenLayers: 1,
            hiddenSize: hidden,
            numAttentionHeads: heads,
            intermediateSize: intermediate,
            imageTokenID: imageTokenID,
            maxWidthHeightRatio: nil,
            ropeTheta: Double(ropeTheta)
        )
    }

    private func matrix(_ values: [Float], rows: Int, columns: Int) -> DeepSeekV41Matrix {
        DeepSeekV41Matrix(rows: rows, columns: columns, values: values)
    }

    private func weights() -> DeepSeekV41DenseWeightSource {
        let source = DeepSeekV41DenseWeightSource()
        source.set(matrix(Self.patchEmbedWeight, rows: hidden, columns: 3 * patchSize * patchSize), role: .visionPatchEmbed, layer: nil)
        source.set(Self.patchEmbedBias, role: .visionPatchEmbedBias, layer: nil)
        source.set(Self.blockNorm1Gain, role: .visionBlockNorm1, layer: 0)
        source.set(matrix(Self.blockWqkvWeight, rows: 3 * hidden, columns: hidden), role: .visionBlockWqkv, layer: 0)
        source.set(Self.blockWqkvBias, role: .visionBlockWqkvBias, layer: 0)
        source.set(matrix(Self.blockWoWeight, rows: hidden, columns: hidden), role: .visionBlockWo, layer: 0)
        source.set(Self.blockWoBias, role: .visionBlockWoBias, layer: 0)
        source.set(Self.blockNorm2Gain, role: .visionBlockNorm2, layer: 0)
        source.set(matrix(Self.blockW1Weight, rows: 2 * intermediate, columns: hidden), role: .visionBlockW1, layer: 0)
        source.set(matrix(Self.blockW2Weight, rows: hidden, columns: intermediate), role: .visionBlockW2, layer: 0)
        source.set(Self.finalNormGain, role: .visionFinalNorm, layer: nil)
        source.set(matrix(Self.alignerW1Weight, rows: textHidden, columns: hidden * ratio * ratio), role: .visionAlignerW1, layer: nil)
        source.set(Self.alignerW1Bias, role: .visionAlignerW1Bias, layer: nil)
        source.set(matrix(Self.alignerW2Weight, rows: textHidden, columns: textHidden), role: .visionAlignerW2, layer: nil)
        source.set(Self.alignerW2Bias, role: .visionAlignerW2Bias, layer: nil)
        return source
    }

    private func forward() -> DeepSeekV41VisionForward {
        DeepSeekV41VisionForward(spec: spec(), weights: weights(), textHiddenSize: textHidden)
    }

    // MARK: Helpers

    /// `[token][width]` from the flat literal above.
    private static func rows(_ values: [Float], count: Int, width: Int) -> [[Float]] {
        (0..<count).map { Array(values[($0 * width)..<(($0 + 1) * width)]) }
    }

    private func patchRows() -> [[Float]] {
        Self.rows(Self.patches, count: rows * columns, width: 3 * patchSize * patchSize)
    }

    /// `Linear` without the port's weight lookup: the stages after the patch embed
    /// are fed the reference's own rows, so each test isolates one rule.
    private func apply(_ weight: [Float], rows: Int, columns: Int, to input: [Float]) -> [Float] {
        matrix(weight, rows: rows, columns: columns).apply(input)
    }

    private func assertRows(
        _ actual: [[Float]],
        _ expected: [Float],
        width: Int,
        _ label: String,
        accuracy: Float = 1e-4,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertEqual(actual.count, expected.count / width, "\(label) row count", file: file, line: line)
        for (row, actualRow) in actual.enumerated() {
            for column in 0..<min(width, actualRow.count) {
                XCTAssertEqual(
                    actualRow[column], expected[row * width + column], accuracy: accuracy,
                    "\(label) row \(row) column \(column)", file: file, line: line
                )
            }
        }
    }

    // MARK: Stages

    /// `PatchEmbed.forward`: `proj(x.flatten(1))`, bias included. The flatten order
    /// is channel-major (see `DeepSeekV41VisionPreprocess.patches`), so a port that
    /// flattens pixel-major multiplies the projection by the wrong columns.
    func testPatchEmbeddingMatchesTheReference() {
        let projected = patchRows().map { input in
            var output = apply(Self.patchEmbedWeight, rows: hidden, columns: 3 * patchSize * patchSize, to: input)
            for unit in 0..<hidden { output[unit] += Self.patchEmbedBias[unit] }
            return output
        }
        assertRows(projected, Self.expectedPatchEmbed, width: hidden, "patch embed")
    }

    /// `Attention.forward`: split-half rotary over a 2D shared table, q and k rotated
    /// and v not, fully bidirectional softmax at `1/sqrt(head_dim)`, then `wo`.
    func testAttentionMatchesTheReference() {
        let rotary = DeepSeekV41VisionForward.rotaryTables(
            rows: rows, columns: columns, ropeDim: ropeDim, theta: ropeTheta
        )
        let patchEmbed = Self.rows(Self.expectedPatchEmbed, count: rows * columns, width: hidden)
        let normalized = DeepSeekV41VisionForward.rmsNorm(
            patchEmbed, weight: Self.blockNorm1Gain, dimension: hidden
        )
        let qkv = normalized.map { input in
            var output = apply(Self.blockWqkvWeight, rows: 3 * hidden, columns: hidden, to: input)
            for unit in 0..<(3 * hidden) { output[unit] += Self.blockWqkvBias[unit] }
            return output
        }
        let attended = DeepSeekV41VisionForward.attention(
            qkv: qkv,
            heads: heads,
            headDim: hidden / heads,
            ropeDim: ropeDim,
            cosine: rotary.cosine,
            sine: rotary.sine
        )
        let projected = attended.map { input in
            var output = apply(Self.blockWoWeight, rows: hidden, columns: hidden, to: input)
            for unit in 0..<hidden { output[unit] += Self.blockWoBias[unit] }
            return output
        }
        assertRows(projected, Self.expectedAttn, width: hidden, "attention")
    }

    /// `MLP.forward`: `w1` emits gate and up, ONLY the gate is activated, and `w2`
    /// projects back. Activating both halves (or the wrong half) keeps the shapes
    /// and changes every number.
    func testTheMLPActivatesOnlyTheGateHalf() {
        let patchEmbed = Self.rows(Self.expectedPatchEmbed, count: rows * columns, width: hidden)
        let attn = Self.rows(Self.expectedAttn, count: rows * columns, width: hidden)
        let afterAttention = zip(patchEmbed, attn).map { left, right in
            zip(left, right).map { $0 + $1 }
        }
        let normalized = DeepSeekV41VisionForward.rmsNorm(
            afterAttention, weight: Self.blockNorm2Gain, dimension: hidden
        )
        let mlp = normalized.map { input -> [Float] in
            let gateAndUp = apply(Self.blockW1Weight, rows: 2 * intermediate, columns: hidden, to: input)
            var activated = [Float](repeating: 0, count: intermediate)
            for unit in 0..<intermediate {
                activated[unit] = DeepSeekV41VisionForward.silu(gateAndUp[unit]) * gateAndUp[intermediate + unit]
            }
            return apply(Self.blockW2Weight, rows: hidden, columns: intermediate, to: activated)
        }
        assertRows(mlp, Self.expectedMlp, width: hidden, "mlp")
    }

    /// The reference's stage outputs have to add up the way `Block.forward` says:
    /// `x + attn` then `+ mlp` is the block's output, and `ViT.forward` returns the
    /// norm of it. The first half checks the VECTORS (a mis-captured hook would leave
    /// `expectedBlock` inconsistent with its own branches); the second half checks the
    /// port's `RMSNorm` against the reference's.
    func testTheResidualAdditionsAddUpAndTheFinalNormMatches() {
        let patchEmbed = Self.rows(Self.expectedPatchEmbed, count: rows * columns, width: hidden)
        let attn = Self.rows(Self.expectedAttn, count: rows * columns, width: hidden)
        let mlp = Self.rows(Self.expectedMlp, count: rows * columns, width: hidden)
        let block = patchEmbed.indices.map { token in
            patchEmbed[token].indices.map { axis in
                patchEmbed[token][axis] + attn[token][axis] + mlp[token][axis]
            }
        }
        assertRows(block, Self.expectedBlock, width: hidden, "patch embed + attn + mlp")
        let normalized = DeepSeekV41VisionForward.rmsNorm(
            Self.rows(Self.expectedBlock, count: rows * columns, width: hidden),
            weight: Self.finalNormGain,
            dimension: hidden
        )
        assertRows(normalized, Self.expectedNormalized, width: hidden, "final norm")
    }

    /// End to end: `encode` must reproduce the reference's aligner rows. This is the
    /// only test that runs the port's own stage order, its `F.unfold` unshuffle, its
    /// `gelu`, and its weight bindings, so a wrong role name or a transposed aligner
    /// matrix shows up here even when every stage above passes.
    func testTheWholeTowerMatchesTheReference() throws {
        let encoded = try forward().encode(patches: patchRows(), rows: rows, columns: columns)
        XCTAssertEqual(encoded.count, 2, "3 patch columns at a ratio of 2 gives two cells")
        assertRows(encoded, Self.expectedAligner, width: textHidden, "aligner")
    }

    // MARK: The image span's token

    /// An image span is a RUN of one token: `image_processor.prepare_vl_inputs` writes
    /// `args.image_token_id` at every position and keeps the start/image/newline/end
    /// distinction in a parallel `token_types` array. So the port's marker must be
    /// spelled exactly as the tokenizer spells id 129264, or the prompt renders a
    /// sequence the model never saw.
    ///
    /// The codepoints are `encoding/encoding.py`'s `IMAGE_PLACEHOLDER`, whose added
    /// token carries `config.json`'s `image_token_id`. A retyped spelling is what this
    /// test exists to catch: `<|image|>` and similar look right and tokenize into six
    /// pieces.
    func testTheMarkerIsTheCheckpointsImageTokenSpelling() {
        let markers = DeepSeekV41VisionMarkers.familyDefault
        XCTAssertEqual(
            Array(markers.imagePlaceholder.unicodeScalars.map(\.value)),
            Self.markerCodepoints
        )
        XCTAssertEqual(
            Array(markers.imageToken.unicodeScalars.map(\.value)),
            Self.markerCodepoints,
            "every span position carries the same token"
        )
        XCTAssertEqual(spec().imageTokenID, imageTokenID)
    }

    /// The placeholder is what a caller writes and the image token is what the span
    /// expands to, so expansion has to turn ONE marker into the whole span and move
    /// nothing around it.
    ///
    /// The two spellings are the same string (one id at every span position), so the
    /// run's LENGTH is the only thing text can show: an expanded span and an
    /// unexpanded marker look alike, and `token_types` / `ExpansionReport` carry the
    /// distinction, exactly as in the checkpoint.
    func testExpansionReplacesOneMarkerWithTheSpan() {
        let markers = DeepSeekV41VisionMarkers.familyDefault
        // 8x12 pixels at a stride of 4 is a 2x3 aligner grid.
        let fitted = DeepSeekV41VisionLayout.fit(width: 8, height: 12, spec: spec())
        XCTAssertEqual(fitted.columns, 2)
        XCTAssertEqual(fitted.rows, 3)
        let expanded = DeepSeekV41VisionLayout.expand(
            text: "before " + markers.imagePlaceholder + " after",
            images: [(width: 8, height: 12)],
            spec: spec(),
            markers: markers
        )
        XCTAssertEqual(
            expanded,
            "before " + String(repeating: markers.imageToken, count: fitted.tokens) + " after"
        )
        XCTAssertEqual(
            fitted.tokens,
            DeepSeekV41VisionLayout.imageTokenCount(columns: 2, rows: 3)
        )
    }
}

// MARK: - Prefill chunk

/// What a chunk of positions reads and what it pools: the two rules a batched
/// prefill has to reproduce, taken from `get_window_topk_idxs` and from both
/// branches of `Compressor.forward`.
///
/// The port walks a prompt one position at a time. A chunk pass computes the same
/// numbers in a different ORDER, and order is exactly what the two positional rules
/// here can break: which window rows a query reads once they have been written into
/// the ring, and which groups a chunk completes when its length is not a multiple
/// of the ratio. The reference answers both, so both are asserted instead of being
/// re-derived from the architecture description.
///
/// `chunkRows` and `stepRows` are the same rows from the two branches, and they are
/// equal to the last bit of a Float32 only by luck: the reductions run in tensor
/// shapes of different rank, so they are compared at the tolerance the reference's
/// own FP32 order justifies. The claim a batched port makes is that they agree, not
/// that they are the same bits.
final class DeepSeekV41ChunkGoldenTests: XCTestCase {

    private let window = 3
    private let positions = 5
    private let ratio = 2
    private let width = 4
    private let hidden = 8

    /// `[position][dim]`, the chunk's block inputs in ascending position order.
    private static let inputs: [Float] = [
        0.25, 0.5, 0.75, 1.0, 1.25, 1.5, 1.75, 2.0,
        2.25, 2.5, 2.75, 3.0, 3.25, 3.5, 3.75, 4.0,
        4.25, 4.5, 4.75, 5.0, 5.25, 5.5, 5.75, 6.0,
        6.25, 6.5, 6.75, 7.0, 7.25, 7.5, 7.75, 8.0,
        8.25, 8.5, 8.75, 9.0, 9.25, 9.5, 9.75, 10.0,
    ]

    /// `attn.compressor.wkv`, `[head_dim][dim]`, row-major.
    private static let kvWeight: [Float] = [
        -0.2743486762046814, -0.29252973198890686, -0.11096779257059097, 0.2449793964624405, 0.1938299536705017, 0.0271333996206522, 0.5312392115592957, -0.23078827559947968,
        -0.10173508524894714, -0.10976564139127731, -0.32761093974113464, -0.18267247080802917, -0.9094019532203674, -0.20123140513896942, 0.015708519145846367, -0.18294356763362885,
        0.14256815612316132, -0.3770979046821594, 0.584096372127533, 0.02197224833071232, -0.42252734303474426, -0.21017824113368988, -0.42883339524269104, 0.207710862159729,
        -0.26240235567092896, 0.2526072561740875, 0.5875536203384399, 0.28500065207481384, -0.07786837220191956, -0.3613465428352356, -0.4851985275745392, -0.040346261113882065,
    ]

    /// `attn.compressor.wgate`, `[head_dim][dim]`, row-major.
    private static let gateWeight: [Float] = [
        -0.2961757779121399, -0.19481568038463593, 0.0826670229434967, 0.5185345411300659, 0.10048672556877136, -0.31101828813552856, -0.39707642793655396, -0.09807982295751572,
        0.15090014040470123, -0.021074937656521797, -0.41118288040161133, 0.9671960473060608, -0.21570582687854767, 0.29945796728134155, -0.3636859655380249, -0.35620594024658203,
        -0.2053443193435669, 0.07546232640743256, 0.22728553414344788, 0.41214895248413086, -0.18166284263134003, -0.22688943147659302, 0.07892361283302307, -0.0828431099653244,
        0.19894123077392578, 0.19902102649211884, -0.22693189978599548, -0.2658155858516693, 0.02506062760949135, 0.002452727174386382, 0.21632415056228638, -0.07565955817699432,
    ]

    /// `[row][head_dim]`: what `Compressor.forward(x, start_pos=0)` returns for the
    /// chunk, i.e. `len // ratio` rows and no row for the trailing remainder.
    private static let chunkRows: [Float] = [
        0.7392598390579224, -4.384644985198975, -1.4002892971038818, -0.892249584197998,
        1.0934498310089111, -12.383255004882812, -3.329446315765381, -1.3002517223358154,
    ]

    /// The same rows from the decode branch, one position per call.
    private static let stepRows: [Float] = [
        0.7392597794532776, -4.384644508361816, -1.4002890586853027, -0.892249584197998,
        1.0934498310089111, -12.383255004882812, -3.329446315765381, -1.3002517223358154,
    ]

    /// `[query][slot]`: the chunk positions each query reads, -1 where that query has
    /// not reached the slot yet.
    private static let chunkWindowSlots: [[Int]] = [
        [0, -1, -1],
        [0, 1, -1],
        [0, 1, 2],
        [1, 2, 3],
        [2, 3, 4],
    ]

    /// The same window after it has been written into the ring, listed oldest slot
    /// first, -1 where the sequence has not filled that slot.
    private static let decodeWindowSlots: [(startPos: Int, slots: [Int])] = [
        (0, [0]),
        (1, [-1, 0, 1]),
        (3, [1, 2, 0]),
        (7, [2, 0, 1]),
    ]

    /// One entry per position: whether the walk pooled a row there. It is also the
    /// per-query compressed visibility, since a row a position produced is a row the
    /// positions after it may read.
    private static let stepProducedAt = [false, true, false, true, false]

    private func geometry() -> DeepSeekV41CacheGeometry {
        DeepSeekV41CacheGeometry(
            width: width,
            precision: .fp16,
            windowRows: window,
            compressedRows: 0,
            indexerKeyWidth: 0,
            candidateBlocks: 0
        )
    }

    func testEachQueryInAChunkReadsItsOwnCausalWindow() {
        for (query, slots) in Self.chunkWindowSlots.enumerated() {
            let expected = slots.filter { $0 >= 0 }
            let range = DeepSeekV41CacheAddressing.windowRange(
                position: query, windowSize: window
            )
            XCTAssertEqual(Array(range), expected, "query \(query)")
        }
    }

    /// A decode step reads the same ring, not the chunk's key matrix, so the slots it
    /// names are physical rows rotated to start at the oldest one still live.
    func testADecodeStepReadsTheRingRotatedOldestFirst() {
        for (startPos, slots) in Self.decodeWindowSlots {
            let rows = DeepSeekV41CacheAddressing.windowRange(
                position: startPos, windowSize: window
            ).map { DeepSeekV41CacheAddressing.windowRow(for: $0, geometry: geometry()) }
            XCTAssertEqual(rows, slots.filter { $0 >= 0 }, "start_pos \(startPos)")
        }
    }

    func testAChunkCompletesExactlyTheGroupsTheWalkCompletes() {
        var produced = 0
        for (position, pooled) in Self.stepProducedAt.enumerated() {
            XCTAssertEqual(
                DeepSeekV41CacheAddressing.compressorCompletesGroup(
                    position: position, ratio: ratio
                ),
                pooled,
                "position \(position) pools"
            )
            if pooled { produced += 1 }
            XCTAssertEqual(
                DeepSeekV41CacheAddressing.compressedRowCount(
                    afterPosition: position, ratio: ratio
                ),
                produced,
                "rows visible to position \(position)"
            )
        }
        XCTAssertEqual(produced, Self.chunkRows.count / width)
    }

    func testTheChunkPoolsWhatTheWalkPools() {
        for row in 0..<(Self.chunkRows.count / width) {
            let inputs = DeepSeekV41CacheAddressing.poolRange(row: row, ratio: ratio).map { position in
                let start = position * hidden
                return Array(Self.inputs[start..<(start + hidden)])
            }
            let pooled = DeepSeekV41Compressor.pooledLatent(
                inputs: inputs,
                kvWeight: DeepSeekV41Matrix(rows: width, columns: hidden, values: Self.kvWeight),
                gateWeight: DeepSeekV41Matrix(rows: width, columns: hidden, values: Self.gateWeight)
            )
            for dimension in 0..<width {
                XCTAssertEqual(
                    pooled[dimension],
                    Self.chunkRows[row * width + dimension],
                    accuracy: 1e-5,
                    "row \(row) dim \(dimension) against the chunk branch"
                )
                XCTAssertEqual(
                    pooled[dimension],
                    Self.stepRows[row * width + dimension],
                    accuracy: 1e-5,
                    "row \(row) dim \(dimension) against the decode branch"
                )
            }
        }
    }
}


