    // MARK: Harness

    private func matrix(_ rows: [[Float]]) -> DeepSeekV41Matrix {
        DeepSeekV41Matrix(rows: rows.count, columns: rows.first?.count ?? 0, values: rows.flatMap { $0 })
    }

    private func makeConfig() throws -> DeepSeekV41Config {
        try DeepSeekV41Config.decode(jsonData: Data(Self.configJSON.utf8))
    }

    private struct Harness {
        let forward: DeepSeekV41CPUForward
        let block: DeepSeekV41DSparkBlock
    }

    /// A forward over the golden's weights, plus the draft block on top of it.
    private func makeHarness() throws -> Harness {
        let config = try makeConfig()
        let plan = try config.makeLayerPlan()
        let source = DeepSeekV41DenseWeightSource()
        func store(
            _ rows: [[Float]],
            _ role: DeepSeekV41TensorRole,
            scope: DeepSeekV41TensorScope,
            layer: Int,
            expert: Int? = nil
        ) {
            source.set(matrix(rows), role: role, scope: scope, layer: layer, expert: expert)
        }
        func store(
            _ values: [Float],
            _ role: DeepSeekV41TensorRole,
            scope: DeepSeekV41TensorScope,
            layer: Int
        ) {
            source.set(values, role: role, scope: scope, layer: layer)
        }

        // Model-level tensors are unscoped: the checkpoint publishes one embedding and
        // one head, and every `mtp` stage borrows them.
        source.set(matrix(Self.embed), role: .tokenEmbedding, layer: nil)
        source.set(matrix(Self.lmHead), role: .lmHead, layer: nil)
        source.set(matrix(Self.mainProj), role: .draftMainProj, scope: .draft, layer: 0)
        source.set(Self.mainNorm, role: .draftMainNorm, scope: .draft, layer: 0)
        source.set(matrix(Self.confidence), role: .draftConfidence, scope: .draft, layer: stageCount - 1)
        source.set(Self.finalNorm, role: .draftNorm, scope: .draft, layer: stageCount - 1)
        source.set(matrix(Self.markovEmbed), role: .draftMarkovEmbed, scope: .draft, layer: stageCount - 1)
        source.set(matrix(Self.markovHead), role: .draftMarkovHead, scope: .draft, layer: stageCount - 1)
        store(Self.stage0WqA, .attnWqA, scope: .draft, layer: 0)
        store(Self.stage0QNorm, .attnWqANorm, scope: .draft, layer: 0)
        store(Self.stage0WqB, .attnWqB, scope: .draft, layer: 0)
        store(Self.stage0Wkv, .attnWkv, scope: .draft, layer: 0)
        store(Self.stage0KvNorm, .attnKvNorm, scope: .draft, layer: 0)
        store(Self.stage0WoA, .attnWoA, scope: .draft, layer: 0)
        store(Self.stage0WoB, .attnWoB, scope: .draft, layer: 0)
        store(Self.stage0Sink, .attnSink, scope: .draft, layer: 0)
        store(Self.stage0AttnNorm, .attnNorm, scope: .draft, layer: 0)
        store(Self.stage0FfnNorm, .ffnNorm, scope: .draft, layer: 0)
        store(Self.stage0HcAttnFn, .hcAttnFn, scope: .draft, layer: 0)
        store(Self.stage0HcAttnBase, .hcAttnBase, scope: .draft, layer: 0)
        store(Self.stage0HcAttnScale, .hcAttnScale, scope: .draft, layer: 0)
        store(Self.stage0HcFfnFn, .hcFfnFn, scope: .draft, layer: 0)
        store(Self.stage0HcFfnBase, .hcFfnBase, scope: .draft, layer: 0)
        store(Self.stage0HcFfnScale, .hcFfnScale, scope: .draft, layer: 0)
        store(Self.stage0Router, .routerWeight, scope: .draft, layer: 0)
        store(Self.stage0RouterBias, .routerBias, scope: .draft, layer: 0)
        store(Self.stage0Expert0W1, .expertW1, scope: .draft, layer: 0, expert: 0)
        store(Self.stage0Expert0W3, .expertW3, scope: .draft, layer: 0, expert: 0)
        store(Self.stage0Expert0W2, .expertW2, scope: .draft, layer: 0, expert: 0)
        store(Self.stage0Expert1W1, .expertW1, scope: .draft, layer: 0, expert: 1)
        store(Self.stage0Expert1W3, .expertW3, scope: .draft, layer: 0, expert: 1)
        store(Self.stage0Expert1W2, .expertW2, scope: .draft, layer: 0, expert: 1)
        store(Self.stage0Expert2W1, .expertW1, scope: .draft, layer: 0, expert: 2)
        store(Self.stage0Expert2W3, .expertW3, scope: .draft, layer: 0, expert: 2)
        store(Self.stage0Expert2W2, .expertW2, scope: .draft, layer: 0, expert: 2)
        store(Self.stage0SharedW1, .sharedExpertW1, scope: .draft, layer: 0)
        store(Self.stage0SharedW3, .sharedExpertW3, scope: .draft, layer: 0)
        store(Self.stage0SharedW2, .sharedExpertW2, scope: .draft, layer: 0)
        store(Self.stage1WqA, .attnWqA, scope: .draft, layer: 1)
        store(Self.stage1QNorm, .attnWqANorm, scope: .draft, layer: 1)
        store(Self.stage1WqB, .attnWqB, scope: .draft, layer: 1)
        store(Self.stage1Wkv, .attnWkv, scope: .draft, layer: 1)
        store(Self.stage1KvNorm, .attnKvNorm, scope: .draft, layer: 1)
        store(Self.stage1WoA, .attnWoA, scope: .draft, layer: 1)
        store(Self.stage1WoB, .attnWoB, scope: .draft, layer: 1)
        store(Self.stage1Sink, .attnSink, scope: .draft, layer: 1)
        store(Self.stage1AttnNorm, .attnNorm, scope: .draft, layer: 1)
        store(Self.stage1FfnNorm, .ffnNorm, scope: .draft, layer: 1)
        store(Self.stage1HcAttnFn, .hcAttnFn, scope: .draft, layer: 1)
        store(Self.stage1HcAttnBase, .hcAttnBase, scope: .draft, layer: 1)
        store(Self.stage1HcAttnScale, .hcAttnScale, scope: .draft, layer: 1)
        store(Self.stage1HcFfnFn, .hcFfnFn, scope: .draft, layer: 1)
        store(Self.stage1HcFfnBase, .hcFfnBase, scope: .draft, layer: 1)
        store(Self.stage1HcFfnScale, .hcFfnScale, scope: .draft, layer: 1)
        store(Self.stage1Router, .routerWeight, scope: .draft, layer: 1)
        store(Self.stage1RouterBias, .routerBias, scope: .draft, layer: 1)
        store(Self.stage1Expert0W1, .expertW1, scope: .draft, layer: 1, expert: 0)
        store(Self.stage1Expert0W3, .expertW3, scope: .draft, layer: 1, expert: 0)
        store(Self.stage1Expert0W2, .expertW2, scope: .draft, layer: 1, expert: 0)
        store(Self.stage1Expert1W1, .expertW1, scope: .draft, layer: 1, expert: 1)
        store(Self.stage1Expert1W3, .expertW3, scope: .draft, layer: 1, expert: 1)
        store(Self.stage1Expert1W2, .expertW2, scope: .draft, layer: 1, expert: 1)
        store(Self.stage1Expert2W1, .expertW1, scope: .draft, layer: 1, expert: 2)
        store(Self.stage1Expert2W3, .expertW3, scope: .draft, layer: 1, expert: 2)
        store(Self.stage1Expert2W2, .expertW2, scope: .draft, layer: 1, expert: 2)
        store(Self.stage1SharedW1, .sharedExpertW1, scope: .draft, layer: 1)
        store(Self.stage1SharedW3, .sharedExpertW3, scope: .draft, layer: 1)
        store(Self.stage1SharedW2, .sharedExpertW2, scope: .draft, layer: 1)

        let forward = DeepSeekV41CPUForward(config: config, plan: plan, weights: source)
        return Harness(forward: forward, block: DeepSeekV41DSparkBlock(forward: forward))
    }

    /// Seeds every stage from the prefix, then drafts.
    private func run() throws -> (Harness, DeepSeekV41DSpark.Draft) {
        let harness = try makeHarness()
        let rows = Self.mainHiddenPrefix
        harness.block.seed(harness.block.mainX(rows))
        let step = harness.block.mainX(Self.mainHiddenStep)
        let draft = harness.block.draft(
            token: seedToken,
            mainX: step[0],
            startPosition: startPosition,
            temperature: 0
        )
        return (harness, draft)
    }

    // MARK: Tests



    func testTheProjectionMatchesTheReference() throws {
        let harness = try makeHarness()
        let projected = harness.block.mainX(Self.mainHiddenPrefix)
        XCTAssertEqual(projected.count, prefixLength)
        assertClose(projected, Self.mainXPrefix, label: "main_x")
        let step = harness.block.mainX(Self.mainHiddenStep)
        assertClose(step, Self.mainXStep, label: "main_x (step)")
    }

    func testTheDraftStackIsTheTokenThenNoise() throws {
        let harness = try makeHarness()
        let stack = harness.block.draftStack(token: seedToken)
        XCTAssertEqual(stack.count, blockSize)
        for (position, entry) in stack.enumerated() {
            XCTAssertEqual(entry.count, copies)
            // Every copy starts identical, and every position but the first carries the
            // noise token: a stack that broadcast the seed across the block would
            // condition every draft on the target's own token.
            let expected = position == 0
                ? Self.embed[seedToken]
                : Self.embed[15]
            for copy in entry {
                XCTAssertEqual(copy, expected)
            }
        }
        assertClose(stack.map { $0[0] }, Self.draftEmbedding, label: "draft stack")
    }

    /// The seed is the `start_pos == 0` branch: it writes `kv_norm(wkv(main_x))`
    /// rows and returns. A prefix longer than the window keeps its LAST rows,
    /// rotated so slot `length % window` holds the oldest survivor.
    func testTheSeedKeepsTheLastWindowRotated() throws {
        let harness = try makeHarness()
        harness.block.seed(harness.block.mainX(Self.mainHiddenPrefix))
        XCTAssertEqual(harness.block.windows.count, stageCount)
        for ring in harness.block.windows {
            XCTAssertEqual(ring.count, windowSize)
        }
        assertClose(harness.block.windows, Self.windowAfterSeed, label: "seeded ring")
    }

    /// The other branch: a prefix that fits lands in slot order, and the slots past
    /// it stay zero.
    func testAShortPrefixLandsInSlotOrder() throws {
        let harness = try makeHarness()
        let rows = Array(Self.mainHiddenPrefix.prefix(windowSize - 1))
        harness.block.seed(harness.block.mainX(rows))
        assertClose(
            harness.block.windows[0],
            Self.windowAfterShortSeed,
            label: "short seed ring"
        )
    }

    /// The draft writes the target's newest position into slot `start % window`
    /// BEFORE the queries gather the ring, so that slot is attended over from the
    /// position it replaced.
    func testTheDraftOverwritesOneRingSlot() throws {
        let (harness, _) = try run()
        assertClose(harness.block.windows, Self.windowAfterDraft, label: "draft ring")
    }

    /// Stage 0's attention input, rotated query and `sparse_attn` output, which is
    /// where the row list, the rope positions and the sink all show up.
    func testTheDraftAttendsLikeTheReference() throws {
        let (harness, _) = try run()
        guard let trace = harness.block.lastTrace else {
            return XCTFail("the draft left no trace")
        }
        assertClose(trace.attentionInputs, Self.attentionInput, label: "attention input")
        assertClose(trace.queries, Self.attentionQuery, label: "query")
        assertClose(trace.attended, Self.attentionOut, label: "attended")
        assertClose(trace.projected, Self.attentionProjected, label: "attention projected")
        assertClose(trace.postAttention, Self.postAttention, label: "post attention")
        assertClose(trace.ffnInputs, Self.ffnInput, label: "ffn input")
        assertClose(trace.ffnOutputs, Self.ffnOutput, label: "ffn")
    }

    /// Both stages in order, so a port that ran one stage's weights twice, or that
    /// fed stage 1 the wrong mix, cannot reproduce the chained stack.
    func testTheStagesChainLikeTheReference() throws {
        let (harness, _) = try run()
        guard let trace = harness.block.lastTrace else {
            return XCTFail("the draft left no trace")
        }
        XCTAssertEqual(trace.stageOutputs.count, stageCount)
        for (stage, output) in trace.stageOutputs.enumerated() {
            assertClose(output, Self.stageOut[stage], label: "stage \(stage)")
        }
        assertClose(trace.preMix, Self.expectedPreMix, label: "pre mix")
    }

    func testTheHeadSeesTheReferencesCollapse() throws {
        let (harness, _) = try run()
        guard let trace = harness.block.lastTrace else {
            return XCTFail("the draft left no trace")
        }
        assertClose(trace.headInputs, Self.headInput, label: "head input")
        assertClose(trace.logits, Self.blockLogits, label: "block logits")
    }

    func testTheChainDrawsTheReferencesTokens() throws {
        let (_, draft) = try run()
        XCTAssertEqual(
            draft.tokens,
            Self.expectedTokens,
            "the markov chain, which is what the block is FOR"
        )
        XCTAssertEqual(draft.confidences.count, Self.expectedConfidence.count)
        for (step, value) in Self.expectedConfidence.enumerated() where step < draft.confidences.count {
            XCTAssertEqual(draft.confidences[step], value, accuracy: 1e-5, "confidence \(step)")
        }
    }

    private func assertClose(
        _ actual: [[Float]],
        _ expected: [[Float]],
        label: String,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertEqual(actual.count, expected.count, "\(label): rows", file: file, line: line)
        for (index, row) in expected.enumerated() where index < actual.count {
            XCTAssertEqual(
                actual[index].count,
                row.count,
                "\(label): row \(index) width",
                file: file,
                line: line
            )
            for (dim, value) in row.enumerated() where dim < actual[index].count {
                XCTAssertEqual(
                    actual[index][dim],
                    value,
                    accuracy: 1e-5,
                    "\(label): [\(index)][\(dim)]",
                    file: file,
                    line: line
                )
            }
        }
    }
    private func assertClose(
        _ actual: [[[Float]]],
        _ expected: [[[Float]]],
        label: String,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        XCTAssertEqual(actual.count, expected.count, "\(label): stages", file: file, line: line)
        for (index, block) in expected.enumerated() where index < actual.count {
            assertClose(actual[index], block, label: "\(label) \(index)", file: file, line: line)
        }
    }
}
